const plugins = [
  { name: "api", deps: ["db", "cache"] },
  { name: "cache", deps: ["db"] },
  { name: "db", deps: [] },
];

function startOrder(plugins) {
  const byName = new Map(plugins.map((p) => [p.name, p]));
  const order = [];
  function visit(name) {
    if (order.includes(name)) return;
    for (const dep of byName.get(name).deps) visit(dep);
    order.push(name);
  }
  for (const plugin of plugins) visit(plugin.name);
  return order;
}

console.log(startOrder(plugins));

