function satisfiesCaret(version, minimum) {
  const [major, minor, patch] = version.split(".").map(Number);
  const [minMajor, minMinor, minPatch] = minimum.split(".").map(Number);
  if (major !== minMajor) return false;
  if (minor !== minMinor) return minor > minMinor;
  return patch >= minPatch;
}

console.log(
  satisfiesCaret("1.4.0", "1.2.0"),
  satisfiesCaret("2.0.0", "1.2.0"),
  satisfiesCaret("1.1.9", "1.2.0"),
  satisfiesCaret("1.2.0", "1.2.0"),
);

