function createCleanupList() {
  const fns = [];
  return {
    add(fn) {
      fns.push(fn);
    },
    runAll() {
      for (const fn of [...fns].reverse()) fn();
    },
  };
}

const cleanup = createCleanupList();
cleanup.add(() => console.log("close file"));
cleanup.add(() => console.log("clear timer"));
cleanup.runAll();

